/*
 * _textures.js — REAL public-domain source imagery, embedded.
 *
 * Every image below is genuine NASA/ESA/Hubble public-domain photography, not a
 * rendering: the Earth maps are the Blue Marble and Earth-at-Night equirectangular
 * datasets (they wrap a sphere exactly), and the deep field is the Hubble eXtreme
 * Deep Field — every smudge in it is a real galaxy. They are embedded as data URIs
 * so the app stays a single offline file.
 *
 * NOTE ON THE SMALL SCALES: below the biome there is no photograph to use — a
 * protein, a nucleotide and an atom have never been photographed in this sense, and
 * are always rendered from structural data. Those stages stay procedurally modelled
 * in 3D, which is exactly what scientific visualisation does.
 *
 * Credit: NASA / NASA Earth Observatory / NASA-ESA Hubble Space Telescope (public domain).
 */
const TEX_CREDIT = 'Imagery: NASA · NASA Earth Observatory · NASA/ESA Hubble (public domain)';
const TEX = {
  // NASA Blue Marble — equirectangular day map (1024x512, 64KB)
  earthDay: 'data:image/jpeg;base64,',
  // NASA Earth at Night — equirectangular city lights (1024x512, 39KB)
  earthNight: 'data:image/jpeg;base64,',
  // Hubble eXtreme Deep Field — thousands of real galaxies (860x749, 104KB)
  deepField: 'data:image/jpeg;base64,',
  // Hubble spiral galaxy (680x592, 34KB)
  galaxy: 'data:image/jpeg;base64,',
  // Hubble Carina Nebula pillars (680x625, 61KB)
  nebula: 'data:image/jpeg;base64,',
};

/* Load a data-URI texture into three.js with sane colour space + filtering. */
function texLoad(THREE, key, opts) {
  opts = opts || {};
  const t = new THREE.TextureLoader().load(TEX[key]);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 8;
  if (opts.wrap) { t.wrapS = t.wrapT = THREE.RepeatWrapping; }
  return t;
}
